<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>exp09ef1b — O Dossiê Invisível (Protótipo Navegável Lo-Fi)</title>
  <style>
    :root {
      --superficie-base: #FFFFFF;
      --superficie-elevada: #FAFAFA;
      --superficie-midia: #E0E0E0;
      --borda-padrao: #C7C7C7;
      --borda-foco: #1A1A1A;
      --texto-primario: #1A1A1A;
      --texto-secundario: #6B6B6B;
      --acao-primaria: #1A1A1A;
      --acao-secundaria: #EDEDED;

      /* Acento sutil exclusivo da casca da ferramenta de revisão (fora dos quadros) */
      --shell-acento: #2A3B4C;
      --shell-bg: #F0F2F5;
      --shell-sidebar-w: 280px;
      --shell-panel-w: 370px;
      --shell-header-h: 56px;
      --shell-footer-h: 70px;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      -webkit-font-smoothing: antialiased;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--shell-bg);
      color: var(--texto-primario);
      height: 100vh;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    /* BARRA SUPERIOR DA FERRAMENTA */
    header.shell-topbar {
      height: var(--shell-header-h);
      background: #FFFFFF;
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 20px;
      flex-shrink: 0;
      z-index: 10;
    }
    .shell-brand {
      display: flex;
      align-items: center;
      gap: 12px;
      min-width: 0;
    }
    .shell-badge-id {
      background: var(--shell-acento);
      color: #FFFFFF;
      font-size: 12px;
      font-weight: 700;
      padding: 4px 8px;
      border-radius: 4px;
      letter-spacing: 0.5px;
      white-space: nowrap;
    }
    .shell-stage-title {
      font-size: 15px;
      font-weight: 600;
      color: var(--texto-primario);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .shell-topbar-center {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .tag-badge {
      font-size: 11px;
      font-weight: 700;
      padding: 3px 8px;
      border-radius: 3px;
      border: 1px solid var(--borda-padrao);
      background: var(--superficie-elevada);
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .tag-pico {
      background: #1A1A1A;
      color: #FFFFFF;
      border-color: #1A1A1A;
    }
    .tag-aha {
      background: #EDEDED;
      color: #1A1A1A;
      border-color: #1A1A1A;
    }
    .tag-latch {
      background: #E0E0E0;
      color: #1A1A1A;
      border-style: dashed;
    }
    .shell-topbar-nav {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .shell-counter {
      font-size: 13px;
      color: var(--texto-secundario);
      font-weight: 500;
      min-width: 70px;
      text-align: right;
    }
    .btn-nav {
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      color: var(--texto-primario);
      padding: 6px 14px;
      font-size: 13px;
      font-weight: 600;
      border-radius: 4px;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      transition: background 0.15s, border-color 0.15s;
    }
    .btn-nav:hover:not(:disabled) {
      background: var(--acao-secundaria);
      border-color: var(--borda-foco);
    }
    .btn-nav:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }

    /* CORPO PRINCIPAL COM 3 COLUNAS */
    main.shell-body {
      flex: 1;
      display: flex;
      min-height: 0;
      overflow: hidden;
    }

    /* TRILHO DE TELAS (ESQUERDA) */
    nav.shell-rail {
      width: var(--shell-sidebar-w);
      background: #FFFFFF;
      border-right: 1px solid var(--borda-padrao);
      overflow-y: auto;
      overflow-x: hidden;
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      padding: 12px 0;
    }
    .rail-group-title {
      font-size: 11px;
      text-transform: uppercase;
      font-weight: 700;
      letter-spacing: 0.8px;
      color: var(--texto-secundario);
      padding: 12px 16px 6px;
    }
    .rail-item {
      display: flex;
      flex-direction: column;
      padding: 8px 16px;
      cursor: pointer;
      border-left: 3px solid transparent;
      transition: background 0.15s, border-color 0.15s;
      text-decoration: none;
      color: inherit;
    }
    .rail-item:hover {
      background: var(--superficie-elevada);
    }
    .rail-item.active {
      background: var(--superficie-elevada);
      border-left-color: var(--borda-foco);
    }
    .rail-item-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
      margin-bottom: 2px;
    }
    .rail-screen-id {
      font-size: 12px;
      font-weight: 700;
      font-family: monospace;
    }
    .rail-actor-tag {
      font-size: 10px;
      padding: 2px 6px;
      border-radius: 3px;
      background: var(--acao-secundaria);
      color: var(--texto-secundario);
      font-weight: 600;
    }
    .rail-state-desc {
      font-size: 12px;
      color: var(--texto-secundario);
      line-height: 1.3;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .rail-item.active .rail-state-desc {
      color: var(--texto-primario);
      font-weight: 500;
    }

    /* PALCO CENTRAL */
    section.shell-stage-container {
      flex: 1;
      background: #ECEFF1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 20px;
      overflow: auto;
      min-width: 0;
      position: relative;
    }
    .viewport-canvas {
      width: 100%;
      max-width: 1060px;
      height: 640px;
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.06);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      position: relative;
    }
    .canvas-annotation-footer {
      margin-top: 8px;
      font-size: 11px;
      color: var(--texto-secundario);
      text-align: center;
      font-family: monospace;
    }

    /* PAINEL PEDAGÓGICO / ONE-PAGER (DIREITA) */
    aside.shell-info-panel {
      width: var(--shell-panel-w);
      background: #FFFFFF;
      border-left: 1px solid var(--borda-padrao);
      overflow-y: auto;
      overflow-x: hidden;
      flex-shrink: 0;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
    .panel-label {
      font-size: 12px;
      text-transform: uppercase;
      font-weight: 700;
      letter-spacing: 0.8px;
      color: var(--texto-secundario);
    }
    .panel-stage-name {
      font-size: 18px;
      font-weight: 700;
      color: var(--texto-primario);
      line-height: 1.25;
    }
    .panel-content {
      font-size: 14px;
      line-height: 1.5;
      color: var(--texto-primario);
      display: flex;
      flex-direction: column;
      gap: 12px;
      word-break: break-word;
    }
    .panel-box {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      padding: 12px;
      font-size: 13px;
      line-height: 1.45;
    }
    .panel-box-title {
      font-weight: 700;
      margin-bottom: 6px;
      font-size: 13px;
      color: var(--texto-primario);
    }
    .panel-source-declaration {
      margin-top: auto;
      padding-top: 14px;
      border-top: 1px dashed var(--borda-padrao);
      font-size: 12px;
      color: var(--texto-secundario);
      font-style: italic;
    }

    /* RODAPÉ INFORMATIVO DA TELA */
    footer.shell-footer {
      min-height: var(--shell-footer-h);
      background: #FFFFFF;
      border-top: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      padding: 10px 24px;
      gap: 24px;
      flex-shrink: 0;
      flex-wrap: wrap;
    }
    .footer-col {
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 0;
      flex: 1;
    }
    .footer-col.fixed-sm {
      flex: 0 0 160px;
    }
    .footer-col-label {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--texto-secundario);
    }
    .footer-col-value {
      font-size: 13px;
      color: var(--texto-primario);
      font-weight: 500;
      line-height: 1.35;
      word-break: break-word;
    }

    /* ======================================================== */
    /* ESTILOS INTERNOS DOS QUADROS (LO-FI CINZA - TOKENS NATIVOS) */
    /* ======================================================== */
    .screen-view {
      display: none;
      width: 100%;
      height: 100%;
      flex-direction: column;
      background: var(--superficie-base);
      color: var(--texto-primario);
      position: absolute;
      top: 0;
      left: 0;
    }
    .screen-view.active {
      display: flex;
    }

    /* LAYOUT 1: CLONE CHATGPT (DESKTOP WORKSPACE) */
    .gpt-workspace {
      display: flex;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: var(--superficie-base);
    }
    .gpt-sidebar {
      width: 250px;
      background: var(--superficie-elevada);
      border-right: 1px solid var(--borda-padrao);
      display: flex;
      flex-direction: column;
      flex-shrink: 0;
      padding: 14px 12px;
    }
    .gpt-sidebar-header {
      font-size: 13px;
      font-weight: 700;
      padding-bottom: 12px;
      border-bottom: 1px solid var(--borda-padrao);
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .gpt-sidebar-channel {
      font-size: 12px;
      padding: 8px 10px;
      border-radius: 4px;
      background: var(--acao-secundaria);
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .gpt-sidebar-meta {
      margin-top: auto;
      font-size: 11px;
      color: var(--texto-secundario);
      border-top: 1px solid var(--borda-padrao);
      padding-top: 10px;
      line-height: 1.4;
    }
    .gpt-main {
      flex: 1;
      display: flex;
      flex-direction: column;
      min-width: 0;
      background: var(--superficie-base);
    }
    .gpt-thread {
      flex: 1;
      overflow-y: auto;
      padding: 20px 32px;
      display: flex;
      flex-direction: column;
      gap: 18px;
    }
    .gpt-bubble {
      display: flex;
      gap: 12px;
      max-width: 88%;
      line-height: 1.45;
      font-size: 13px;
    }
    .gpt-bubble.user {
      align-self: flex-end;
      flex-direction: row-reverse;
    }
    .gpt-bubble.user .bubble-body {
      background: var(--acao-secundaria);
      padding: 10px 14px;
      border-radius: 12px 12px 2px 12px;
      border: 1px solid var(--borda-padrao);
    }
    .gpt-bubble.assistant {
      align-self: flex-start;
    }
    .gpt-bubble.assistant .bubble-body {
      background: var(--superficie-elevada);
      padding: 12px 16px;
      border-radius: 4px 12px 12px 12px;
      border: 1px solid var(--borda-padrao);
      flex: 1;
    }
    .bubble-avatar {
      width: 28px;
      height: 28px;
      border-radius: 4px;
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 10px;
      font-weight: 700;
      flex-shrink: 0;
    }
    .bubble-body h4 {
      font-size: 13px;
      margin-bottom: 6px;
    }

    /* COMPONENTES EMBED CHATGPT */
    .gpt-suggestions-container {
      display: flex;
      gap: 8px;
      margin-bottom: 10px;
      flex-wrap: wrap;
    }
    .gpt-pill {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      padding: 8px 12px;
      font-size: 12px;
      border-radius: 16px;
      cursor: pointer;
      transition: all 0.15s;
      font-weight: 500;
      color: var(--texto-primario);
    }
    .gpt-pill:hover {
      border-color: var(--borda-foco);
      background: var(--acao-secundaria);
    }
    .gpt-composer-area {
      padding: 14px 32px 18px;
      border-top: 1px solid var(--borda-padrao);
      background: var(--superficie-base);
      display: flex;
      flex-direction: column;
    }
    .gpt-composer-box {
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      display: flex;
      align-items: center;
      padding: 8px 12px;
      background: var(--superficie-elevada);
      gap: 8px;
    }
    .gpt-composer-box.disabled {
      background: var(--acao-secundaria);
      color: var(--texto-secundario);
      cursor: not-allowed;
    }
    .gpt-input-sim {
      flex: 1;
      font-size: 13px;
      color: var(--texto-secundario);
      background: transparent;
      border: none;
      outline: none;
      font-family: inherit;
    }
    .gpt-send-btn {
      width: 28px;
      height: 28px;
      background: var(--acao-primaria);
      color: #FFFFFF;
      border: none;
      border-radius: 4px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
    }

    /* COMPONENTES ESPECÍFICOS DE ETAPA */
    .project-cards-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin: 10px 0;
    }
    .p-card {
      border: 1px solid var(--borda-padrao);
      background: var(--superficie-base);
      padding: 10px;
      border-radius: 4px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .p-card-title {
      font-size: 12px;
      font-weight: 700;
    }
    .p-card-desc {
      font-size: 11px;
      color: var(--texto-secundario);
      line-height: 1.35;
    }
    .p-card-tag {
      font-size: 10px;
      font-weight: 700;
      padding: 2px 5px;
      border-radius: 2px;
      background: var(--acao-secundaria);
      align-self: flex-start;
      margin-top: 4px;
    }

    /* CARD DE DELIBERAÇÃO LATCH (PICO) */
    .latch-card {
      border: 2px solid var(--borda-foco);
      background: var(--superficie-elevada);
      border-radius: 6px;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      max-width: 600px;
      margin: 8px 0;
    }
    .latch-title {
      font-size: 14px;
      font-weight: 700;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .latch-warning {
      font-size: 12px;
      color: var(--texto-secundario);
      border-left: 3px solid var(--borda-foco);
      padding-left: 8px;
    }
    .latch-options-group {
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .radio-option-card {
      border: 1px solid var(--borda-padrao);
      padding: 10px 12px;
      border-radius: 4px;
      background: var(--superficie-base);
      display: flex;
      align-items: center;
      gap: 10px;
      cursor: pointer;
      transition: border-color 0.15s;
    }
    .radio-option-card.selected {
      border: 2px solid var(--borda-foco);
      background: #FFFFFF;
    }
    .radio-circle {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      border: 2px solid var(--borda-padrao);
      flex-shrink: 0;
      position: relative;
    }
    .radio-option-card.selected .radio-circle {
      border-color: var(--borda-foco);
    }
    .radio-option-card.selected .radio-circle::after {
      content: '';
      position: absolute;
      width: 8px;
      height: 8px;
      background: var(--borda-foco);
      border-radius: 50%;
      top: 2px;
      left: 2px;
    }
    .radio-label-wrap {
      flex: 1;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 12px;
      font-weight: 600;
    }
    .tag-waitlist {
      font-size: 10px;
      font-weight: 700;
      padding: 2px 6px;
      background: var(--superficie-midia);
      color: var(--texto-secundario);
      border-radius: 3px;
    }
    .poll-embed {
      border-top: 1px dashed var(--borda-padrao);
      padding-top: 12px;
      margin-top: 4px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }
    .poll-question {
      font-size: 12px;
      font-weight: 700;
      line-height: 1.35;
    }
    .poll-option {
      border: 1px solid var(--borda-padrao);
      padding: 8px 10px;
      border-radius: 4px;
      font-size: 12px;
      cursor: pointer;
      display: flex;
      gap: 8px;
      align-items: flex-start;
      background: var(--superficie-base);
    }
    .poll-option.selected {
      border: 2px solid var(--borda-foco);
      font-weight: 500;
    }
    .btn-latch-homologar {
      background: var(--acao-primaria);
      color: #FFFFFF;
      padding: 10px 16px;
      border-radius: 4px;
      font-size: 13px;
      font-weight: 700;
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      margin-top: 8px;
    }
    .btn-latch-homologar:disabled {
      background: var(--acao-secundaria);
      color: var(--texto-secundario);
      cursor: not-allowed;
    }
    .latch-locked-banner {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      padding: 12px;
      border-radius: 4px;
      font-size: 12px;
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 600;
    }

    /* GAVETA LATERAL DE ANEXO (E2-ALU-02) */
    .drawer-overlay {
      position: absolute;
      top: 0;
      right: 0;
      width: 440px;
      height: 100%;
      background: var(--superficie-base);
      border-left: 2px solid var(--borda-foco);
      box-shadow: -4px 0 16px rgba(0,0,0,0.1);
      display: flex;
      flex-direction: column;
      z-index: 50;
      padding: 18px;
    }
    .drawer-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 1px solid var(--borda-padrao);
      padding-bottom: 10px;
      margin-bottom: 14px;
    }
    .drawer-title {
      font-size: 13px;
      font-weight: 700;
    }
    .facsimile-placeholder {
      height: 160px;
      background: var(--superficie-midia);
      border: 1px dashed var(--borda-padrao);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      position: relative;
      margin: 12px 0;
    }
    .facsimile-x {
      font-size: 40px;
      color: var(--borda-padrao);
      font-weight: 300;
      line-height: 1;
    }
    .facsimile-label {
      font-size: 11px;
      color: var(--texto-secundario);
      font-weight: 600;
    }

    /* SPLIT-VIEW TABELAS (E6-ALU-01) */
    .data-match-container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
      margin: 10px 0;
    }
    .match-table-card {
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      background: var(--superficie-base);
      display: flex;
      flex-direction: column;
    }
    .match-table-title {
      background: var(--superficie-elevada);
      padding: 8px 12px;
      font-size: 12px;
      font-weight: 700;
      border-bottom: 1px solid var(--borda-padrao);
    }
    .match-row {
      padding: 8px 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 1px solid var(--borda-padrao);
      font-size: 12px;
      cursor: pointer;
    }
    .match-row:last-child {
      border-bottom: none;
    }
    .match-row.paired {
      background: var(--acao-secundaria);
      font-weight: 600;
      border-left: 3px solid var(--borda-foco);
    }
    .badge-match-ok {
      font-size: 10px;
      font-weight: 700;
      background: var(--borda-foco);
      color: #FFFFFF;
      padding: 2px 6px;
      border-radius: 3px;
    }

    /* TELAS DO UNOORIA HUB (PROFESSOR / PROJEÇÃO) */
    .hub-layout {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      background: var(--superficie-elevada);
