    let currentIndex = 0;

    function renderRail() {
      const rail = document.getElementById("screenRail");
      rail.innerHTML = "";

      let currentGroup = "";
      SCREENS.forEach((s, idx) => {
        if (s.stageGroup !== currentGroup) {
          currentGroup = s.stageGroup;
          const groupTitle = document.createElement("div");
          groupTitle.className = "rail-group-title";
          groupTitle.textContent = currentGroup;
          rail.appendChild(groupTitle);
        }

        const item = document.createElement("a");
        item.href = "javascript:void(0)";
        item.className = "rail-item" + (idx === currentIndex ? " active" : "");
        item.onclick = () => goToScreenIndex(idx);

        item.innerHTML = `
          <div class="rail-item-header">
            <span class="rail-screen-id">${s.id}</span>
            <span class="rail-actor-tag">${s.actor}</span>
          </div>
          <div class="rail-state-desc">${s.stateName}</div>
        `;
        rail.appendChild(item);
      });
    }

    function updateView() {
      const s = SCREENS[currentIndex];

      // Atualiza Header
      document.getElementById("headerScreenId").textContent = s.id;
      document.getElementById("headerStageName").textContent = s.stageName;
      document.getElementById("navCounter").textContent = `${currentIndex + 1} / ${SCREENS.length}`;

      const badgesContainer = document.getElementById("headerBadges");
      badgesContainer.innerHTML = "";
      s.badges.forEach(b => {
        const span = document.createElement("span");
        span.className = "tag-badge tag-" + b.toLowerCase();
        span.textContent = b;
        badgesContainer.appendChild(span);
      });

      // Atualiza Palco (Telas)
      document.querySelectorAll(".screen-view").forEach(el => {
        if (el.getAttribute("data-screen-id") === s.id) {
          el.classList.add("active");
        } else {
          el.classList.remove("active");
        }
      });

      document.getElementById("canvasFooterLabel").textContent = s.viewportDesc;

      // Atualiza Painel Pedagógico
      const pData = ONE_PAGER_TEXTS[s.onePagerStage];
      if (pData) {
        document.getElementById("panelStageTitle").textContent = pData.title;
        document.getElementById("panelStageContent").innerHTML = `
          <div>${pData.text}</div>
          <div class="panel-box">
            <div class="panel-box-title">Diretriz Não-Negociável:</div>
            ${pData.box}
          </div>
        `;
      }

      // Atualiza Rodapé
      document.getElementById("footScreenId").textContent = s.id + " (" + s.stateName + ")";
      document.getElementById("footAction").textContent = s.footAction;
      document.getElementById("footNextChange").textContent = s.footChange;

      // Botões nav
      document.getElementById("btnPrev").disabled = (currentIndex === 0);
      document.getElementById("btnNext").disabled = (currentIndex === SCREENS.length - 1);

      renderRail();
    }

    function goToScreenIndex(idx) {
      if (idx >= 0 && idx < SCREENS.length) {
        currentIndex = idx;
        updateView();
      }
    }

    function goToScreen(screenId) {
      const idx = SCREENS.findIndex(s => s.id === screenId);
      if (idx !== -1) {
        goToScreenIndex(idx);
      }
    }

    document.getElementById("btnPrev").onclick = () => {
      if (currentIndex > 0) goToScreenIndex(currentIndex - 1);
    };
    document.getElementById("btnNext").onclick = () => {
      if (currentIndex < SCREENS.length - 1) goToScreenIndex(currentIndex + 1);
    };

    // Navegação via teclado
    window.addEventListener("keydown", (e) => {
      if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
      if (e.key === "ArrowLeft") {
        if (currentIndex > 0) goToScreenIndex(currentIndex - 1);
      } else if (e.key === "ArrowRight") {
        if (currentIndex < SCREENS.length - 1) goToScreenIndex(currentIndex + 1);
      }
    });

