    function sendPrompt() {
      const container = document.getElementById("pillsContainer");
      if (container) container.style.display = "none";
      setTimeout(() => goToScreen("E2-ALU-01"), 300);
    }

    function handleInputKey(e) {
      if (e.key === "Enter") {
        sendPrompt();
      }
    }

