      document.querySelectorAll(".radio-option-card").forEach(c => c.classList.remove("selected"));
      if (proj === "mesa") document.getElementById("optMesa").classList.add("selected");
      if (proj === "ponto") document.getElementById("optPonto").classList.add("selected");
      if (proj === "conexao") document.getElementById("optConexao").classList.add("selected");
    }

    function selectPollE3(opt) {
